def wrap(draw,text,x,y,width=1120,size=27,fill='#e5e9ee',bold=False):
 f=font(size,bold); words=text.split(); line=''
 for word in words:
  candidate=(line+' '+word).strip()
  if draw.textlength(candidate,font=f)>width and line: draw.text((x,y),line,font=f,fill=fill);y+=size+9;line=word
  else:line=candidate
 if line:draw.text((x,y),line,font=f,fill=fill);y+=size+9
 return y
